<?php if ( ! defined( 'ABSPATH' ) ) { exit; }
$page = max( 1, absint( $_GET['notes_page'] ?? 1 ) ); $search = sanitize_text_field( wp_unslash( $_GET['q'] ?? '' ) ); $status = sanitize_key( $_GET['status'] ?? '' );
$query = Revayat_Companion_Member_Notes::listing( $args['user']->ID, $page, $search, $status );
$labels = array( 'draft' => 'پیش‌نویس', 'pending' => 'در انتظار بررسی', 'publish' => 'منتشرشده' ); ?>
<div class="rv-member-card"><div class="rv-member-actions"><h2>یادداشت‌های من</h2><a class="rv-member-button" href="<?php echo esc_url( home_url( '/dashboard/?view=note-edit' ) ); ?>">یادداشت تازه</a></div>
<form method="get" class="rv-member-filters"><input type="hidden" name="view" value="notes"><label>جستجو<input name="q" value="<?php echo esc_attr( $search ); ?>"></label><label>وضعیت<select name="status"><option value="">همه</option><?php foreach ( $labels as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $status, $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label><button class="rv-member-secondary">اعمال فیلتر</button></form>
<?php if ( ! $query->posts ) : ?><p class="rv-member-empty">هنوز یادداشتی در این فهرست ندارید.</p><?php endif; ?>
<?php foreach ( $query->posts as $note ) : ?><article class="rv-member-row"><div><span class="rv-member-badge"><?php echo esc_html( $labels[ $note->post_status ] ?? $note->post_status ); ?></span><h3><?php echo esc_html( $note->post_title ); ?></h3><small><?php echo esc_html( get_the_modified_date( 'j F Y', $note ) ); ?></small></div><a href="<?php echo esc_url( 'publish' === $note->post_status ? get_permalink( $note ) : add_query_arg( array( 'view' => 'note-edit', 'post_id' => $note->ID ), home_url( '/dashboard/' ) ) ); ?>"><?php echo 'draft' === $note->post_status ? 'ویرایش یادداشت' : 'مشاهده'; ?></a></article><?php endforeach; ?>
<nav aria-label="صفحه‌های یادداشت‌ها"><?php echo wp_kses_post( paginate_links( array( 'base' => add_query_arg( 'notes_page', '%#%' ), 'format' => '', 'current' => $page, 'total' => $query->max_num_pages ) ) ); ?></nav></div>
